    using CT = ftl::mmio::Field<1, 1, eCT, ftl::mmio::RW, ftl::mmio::Normal>;
    // Offset
    using OFS = ftl::mmio::Field<5, 2, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
