  // LPI Control and Status
  struct MAC_LPI_CONTROL_STATUS_fields_ {
    enum class eTLPIEN : std::uint32_t {
      // Transmit LPI entry not detected
      eINACTIVE = 0,
      // Transmit LPI entry detected
      eACTIVE = 1,
    };

    enum class eTLPIEX : std::uint32_t {
      // Transmit LPI exit not detected
      eINACTIVE = 0,
      // Transmit LPI exit detected
      eACTIVE = 1,
    };

    enum class eRLPIEN : std::uint32_t {
      // Receive LPI entry not detected
      eINACTIVE = 0,
      // Receive LPI entry detected
      eACTIVE = 1,
    };

    enum class eRLPIEX : std::uint32_t {
      // Receive LPI exit not detected
      eINACTIVE = 0,
      // Receive LPI exit detected
      eACTIVE = 1,
    };

    enum class eTLPIST : std::uint32_t {
      // Transmit LPI state not detected
      eINACTIVE = 0,
      // Transmit LPI state detected
      eACTIVE = 1,
    };

    enum class eRLPIST : std::uint32_t {
      // Receive LPI state not detected
      eINACTIVE = 0,
      // Receive LPI state detected
      eACTIVE = 1,
    };

    enum class eLPIEN : std::uint32_t {
      // LPI state is disabled
      eDISABLE = 0,
      // LPI state is enabled
      eENABLE = 1,
    };

    enum class ePLS : std::uint32_t {
      // link is down
      eDISABLE = 0,
      // link is okay (UP)
      eENABLE = 1,
    };

    enum class ePLSEN : std::uint32_t {
      // PHY Link Status is disabled
      eDISABLE = 0,
      // PHY Link Status is enabled
      eENABLE = 1,
    };

    enum class eLPITXA : std::uint32_t {
      // LPI Tx Automate is disabled
      eDISABLE = 0,
      // LPI Tx Automate is enabled
      eENABLE = 1,
    };

    enum class eLPIATE : std::uint32_t {
      // LPI Timer is disabled
      eDISABLE = 0,
      // LPI Timer is enabled
      eENABLE = 1,
    };

    enum class eLPITCSE : std::uint32_t {
      // LPI Tx Clock Stop is disabled
      eDISABLE = 0,
      // LPI Tx Clock Stop is enabled
      eENABLE = 1,
    };

    // Transmit LPI Entry When this bit is set, it indicates that the MAC Transmitter has entered the LPI state because of the setting of the LPIEN bit.
    using TLPIEN = ftl::mmio::Field<1, 0, eTLPIEN, ftl::mmio::RO, ftl::mmio::Normal>;
    // Transmit LPI Exit When this bit is set, it indicates that the MAC transmitter exited the LPI state after the application cleared the LPIEN bit and the LPI TW Timer has expired.
    using TLPIEX = ftl::mmio::Field<1, 1, eTLPIEX, ftl::mmio::RO, ftl::mmio::Normal>;
    // Receive LPI Entry When this bit is set, it indicates that the MAC Receiver has received an LPI pattern and entered the LPI state.
    using RLPIEN = ftl::mmio::Field<1, 2, eRLPIEN, ftl::mmio::RO, ftl::mmio::Normal>;
    // Receive LPI Exit When this bit is set, it indicates that the MAC Receiver has stopped receiving the LPI pattern on the GMII or MII interface, exited the LPI state, and resumed the normal reception.
    using RLPIEX = ftl::mmio::Field<1, 3, eRLPIEX, ftl::mmio::RO, ftl::mmio::Normal>;
    // Transmit LPI State When this bit is set, it indicates that the MAC is transmitting the LPI pattern on the GMII or MII interface.
    using TLPIST = ftl::mmio::Field<1, 8, eTLPIST, ftl::mmio::RO, ftl::mmio::Normal>;
    // Receive LPI State When this bit is set, it indicates that the MAC is receiving the LPI pattern on the GMII or MII interface.
    using RLPIST = ftl::mmio::Field<1, 9, eRLPIST, ftl::mmio::RO, ftl::mmio::Normal>;
    // LPI Enable When this bit is set, it instructs the MAC Transmitter to enter the LPI state.
    using LPIEN = ftl::mmio::Field<1, 16, eLPIEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // PHY Link Status This bit indicates the link status of the PHY.
    using PLS = ftl::mmio::Field<1, 17, ePLS, ftl::mmio::RW, ftl::mmio::Normal>;
    // PHY Link Status Enable This bit enables the link status received on the RGMII, SGMII, or SMII Receive paths to be used for activating the LPI LS TIMER.
    using PLSEN = ftl::mmio::Field<1, 18, ePLSEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // LPI Tx Automate This bit controls the behavior of the MAC when it is entering or coming out of the LPI mode on the Transmit side.
    using LPITXA = ftl::mmio::Field<1, 19, eLPITXA, ftl::mmio::RW, ftl::mmio::Normal>;
    // LPI Timer Enable This bit controls the automatic entry of the MAC Transmitter into and exit out of the LPI state.
    using LPIATE = ftl::mmio::Field<1, 20, eLPIATE, ftl::mmio::RW, ftl::mmio::Normal>;
    // LPI Tx Clock Stop Enable When this bit is set, the MAC asserts sbd_tx_clk_gating_ctrl_o signal high after it enters Tx LPI mode to indicate that the Tx clock to MAC can be stopped.
    using LPITCSE = ftl::mmio::Field<1, 21, eLPITCSE, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MAC_LPI_CONTROL_STATUS_fields_

