  // Frame Preemption Control
  struct MAC_FPE_CTRL_STS_fields_ {
    enum class eEFPE : std::uint32_t {
      // Tx Frame Preemption is disabled
      eDISABLE = 0,
      // Tx Frame Preemption is enabled
      eENABLE = 1,
    };

    enum class eSVER : std::uint32_t {
      // Send Verify mPacket is disabled
      eDISABLE = 0,
      // Send Verify mPacket is enabled
      eENABLE = 1,
    };

    enum class eSRSP : std::uint32_t {
      // Send Respond mPacket is disabled
      eDISABLE = 0,
      // Send Respond mPacket is enabled
      eENABLE = 1,
    };

    enum class eRVER : std::uint32_t {
      // Not received Verify Frame
      eINACTIVE = 0,
      // Received Verify Frame
      eACTIVE = 1,
    };

    enum class eRRSP : std::uint32_t {
      // Not received Respond Frame
      eINACTIVE = 0,
      // Received Respond Frame
      eACTIVE = 1,
    };

    enum class eTVER : std::uint32_t {
      // Not transmitted Verify Frame
      eINACTIVE = 0,
      // transmitted Verify Frame
      eACTIVE = 1,
    };

    enum class eTRSP : std::uint32_t {
      // Not transmitted Respond Frame
      eINACTIVE = 0,
      // transmitted Respond Frame
      eACTIVE = 1,
    };

    // Enable Tx Frame Preemption When set Frame Preemption Tx functionality is enabled.
    using EFPE = ftl::mmio::Field<1, 0, eEFPE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Send Verify mPacket When set indicates hardware to send a verify mPacket.
    using SVER = ftl::mmio::Field<1, 1, eSVER, ftl::mmio::RW, ftl::mmio::Normal>;
    // Send Respond mPacket When set indicates hardware to send a Respond mPacket.
    using SRSP = ftl::mmio::Field<1, 2, eSRSP, ftl::mmio::RW, ftl::mmio::Normal>;
    // Synopsys Reserved, Must be set to "0".
    using S1_SET_0 = ftl::mmio::Field<1, 3, bool, ftl::mmio::RW, ftl::mmio::Normal>;
    // Received Verify Frame Set when a Verify mPacket is received.
    using RVER = ftl::mmio::Field<1, 16, eRVER, ftl::mmio::RW, ftl::mmio::Normal>;
    // Received Respond Frame Set when a Respond mPacket is received.
    using RRSP = ftl::mmio::Field<1, 17, eRRSP, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmitted Verify Frame Set when a Verify mPacket is transmitted (triggered by setting SVER field).
    using TVER = ftl::mmio::Field<1, 18, eTVER, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmitted Respond Frame Set when a Respond mPacket is transmitted (triggered by setting SRSP field).
    using TRSP = ftl::mmio::Field<1, 19, eTRSP, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MAC_FPE_CTRL_STS_fields_

