  struct MAC_MMC_CONTROL_fields_ {
    enum class eCNTRST : std::uint32_t {
      // Counters are not reset
      eDISABLE = 0,
      // All counters are reset
      eENABLE = 1,
    };

    enum class eCNTSTOPRO : std::uint32_t {
      // Counter Stop Rollover is disabled
      eDISABLE = 0,
      // Counter Stop Rollover is enabled
      eENABLE = 1,
    };

    enum class eRSTONRD : std::uint32_t {
      // Reset on Read is disabled
      eDISABLE = 0,
      // Reset on Read is enabled
      eENABLE = 1,
    };

    enum class eCNTFREEZ : std::uint32_t {
      // MMC Counter Freeze is disabled
      eDISABLE = 0,
      // MMC Counter Freeze is enabled
      eENABLE = 1,
    };

    enum class eCNTPRST : std::uint32_t {
      // Counters Preset is disabled
      eDISABLE = 0,
      // Counters Preset is enabled
      eENABLE = 1,
    };

    enum class eCNTPRSTLVL : std::uint32_t {
      // Full-Half Preset is disabled
      eDISABLE = 0,
      // Full-Half Preset is enabled
      eENABLE = 1,
    };

    enum class eUCDBC : std::uint32_t {
      // Update MMC Counters for Dropped Broadcast Packets is disabled
      eDISABLE = 0,
      // Update MMC Counters for Dropped Broadcast Packets is enabled
      eENABLE = 1,
    };

    // Counters Reset When this bit is set, all counters are reset.
    using CNTRST = ftl::mmio::Field<1, 0, eCNTRST, ftl::mmio::RW, ftl::mmio::Normal>;
    // Counter Stop Rollover When this bit is set, the counter does not roll over to zero after reaching the maximum value.
    using CNTSTOPRO = ftl::mmio::Field<1, 1, eCNTSTOPRO, ftl::mmio::RW, ftl::mmio::Normal>;
    // Reset on Read When this bit is set, the MMC counters are reset to zero after Read (self-clearing after reset).
    using RSTONRD = ftl::mmio::Field<1, 2, eRSTONRD, ftl::mmio::RW, ftl::mmio::Normal>;
    // MMC Counter Freeze When this bit is set, it freezes all MMC counters to their current value.
    using CNTFREEZ = ftl::mmio::Field<1, 3, eCNTFREEZ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Counters Preset When this bit is set, all counters are initialized or preset to almost full or almost half according to the CNTPRSTLVL bit.
    using CNTPRST = ftl::mmio::Field<1, 4, eCNTPRST, ftl::mmio::RW, ftl::mmio::Normal>;
    // Full-Half Preset When this bit is low and the CNTPRST bit is set, all MMC counters get preset to almost-half value.
    using CNTPRSTLVL = ftl::mmio::Field<1, 5, eCNTPRSTLVL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Update MMC Counters for Dropped Broadcast Packets Note: The CNTRST bit has a higher priority than the CNTPRST bit.
    using UCDBC = ftl::mmio::Field<1, 8, eUCDBC, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MAC_MMC_CONTROL_fields_

