  // PTP Offload Engine Control
  struct MAC_PTO_CONTROL_fields_ {
    enum class ePTOEN : std::uint32_t {
      // PTP Offload feature is disabled
      eDISABLE = 0,
      // PTP Offload feature is enabled
      eENABLE = 1,
    };

    enum class eASYNCEN : std::uint32_t {
      // Automatic PTP SYNC message is disabled
      eDISABLE = 0,
      // Automatic PTP SYNC message is enabled
      eENABLE = 1,
    };

    enum class eAPDREQEN : std::uint32_t {
      // Automatic PTP Pdelay_Req message is disabled
      eDISABLE = 0,
      // Automatic PTP Pdelay_Req message is enabled
      eENABLE = 1,
    };

    enum class eASYNCTRIG : std::uint32_t {
      // Automatic PTP SYNC message Trigger is disabled
      eDISABLE = 0,
      // Automatic PTP SYNC message Trigger is enabled
      eENABLE = 1,
    };

    enum class eAPDREQTRIG : std::uint32_t {
      // Automatic PTP Pdelay_Req message Trigger is disabled
      eDISABLE = 0,
      // Automatic PTP Pdelay_Req message Trigger is enabled
      eENABLE = 1,
    };

    enum class eDRRDIS : std::uint32_t {
      // PTO Delay Request/Response response generation is enabled
      eENABLE = 0,
      // PTO Delay Request/Response response generation is disabled
      eDISABLE = 1,
    };

    enum class ePDRDIS : std::uint32_t {
      // Peer Delay Response response generation is enabled
      eENABLE = 0,
      // Peer Delay Response response generation is disabled
      eDISABLE = 1,
    };

    // PTP Offload Enable When this bit is set, the PTP Offload feature is enabled.
    using PTOEN = ftl::mmio::Field<1, 0, ePTOEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Automatic PTP SYNC message Enable When this bit is set, PTP SYNC message is generated periodically based on interval programmed or trigger from application, when the MAC is programmed to be in Clock Master mode.
    using ASYNCEN = ftl::mmio::Field<1, 1, eASYNCEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Automatic PTP Pdelay_Req message Enable When this bit is set, PTP Pdelay_Req message is generated periodically based on interval programmed or trigger from application, when the MAC is programmed to be in Peer-to-Peer Transparent mode.
    using APDREQEN = ftl::mmio::Field<1, 2, eAPDREQEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Automatic PTP SYNC message Trigger When this bit is set, one PTP SYNC message is transmitted.
    using ASYNCTRIG = ftl::mmio::Field<1, 4, eASYNCTRIG, ftl::mmio::RW, ftl::mmio::Normal>;
    // Automatic PTP Pdelay_Req message Trigger When this bit is set, one PTP Pdelay_Req message is transmitted.
    using APDREQTRIG = ftl::mmio::Field<1, 5, eAPDREQTRIG, ftl::mmio::RW, ftl::mmio::Normal>;
    // Disable PTO Delay Request/Response response generation When this bit is set, the Delay Request and Delay response is not generated for received SYNC and Delay request packet respectively, as required by the programmed mode.
    using DRRDIS = ftl::mmio::Field<1, 6, eDRRDIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Disable Peer Delay Response response generation When this bit is set, the Peer Delay Response (Pdelay_Resp) response is not be generated for received Peer Delay Request (Pdelay_Req) request packet, as required by the programmed mode.
    using PDRDIS = ftl::mmio::Field<1, 7, ePDRDIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Domain Number This field indicates the domain Number in which the PTP node is operating.
    using DN = ftl::mmio::Field<8, 8, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MAC_PTO_CONTROL_fields_

