  // MTL Operation Mode
  struct MTL_OPERATION_MODE_fields_ {
    enum class eDTXSTS : std::uint32_t {
      // Drop Transmit Status is disabled
      eDISABLE = 0,
      // Drop Transmit Status is enabled
      eENABLE = 1,
    };

    enum class eRAA : std::uint32_t {
      // Strict priority (SP)
      eSP = 0,
      // Weighted Strict Priority (WSP)
      eWSP = 1,
    };

    enum class eSCHALG : std::uint32_t {
      // WRR algorithm
      eWRR = 0,
      // WFQ algorithm when DCB feature is selected.Otherwise, Reserved
      eWFQ = 1,
      // DWRR algorithm when DCB feature is selected.Otherwise, Reserved
      eDWRR = 2,
      // Strict priority algorithm
      eSP = 3,
    };

    enum class eCNTPRST : std::uint32_t {
      // Counters Preset is disabled
      eDISABLE = 0,
      // Counters Preset is enabled
      eENABLE = 1,
    };

    enum class eCNTCLR : std::uint32_t {
      // Counters are not reset
      eDISABLE = 0,
      // All counters are reset
      eENABLE = 1,
    };

    enum class eFRPE : std::uint32_t {
      // Flexible Rx parser is disabled
      eDISABLE = 0,
      // Flexible Rx parser is enabled
      eENABLE = 1,
    };

    // Drop Transmit Status When this bit is set, the Tx packet status received from the MAC is dropped in the MTL.
    using DTXSTS = ftl::mmio::Field<1, 1, eDTXSTS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Arbitration Algorithm This field is used to select the arbitration algorithm for the Rx side.
    using RAA = ftl::mmio::Field<1, 2, eRAA, ftl::mmio::RW, ftl::mmio::Normal>;
    // Tx Scheduling Algorithm This field indicates the algorithm for Tx scheduling:
    using SCHALG = ftl::mmio::Field<2, 5, eSCHALG, ftl::mmio::RW, ftl::mmio::Normal>;
    // Counters Preset When this bit is set, - MTL_TxQ[0-7]_Underflow register is initialized/preset to 12'h7F0.
    using CNTPRST = ftl::mmio::Field<1, 8, eCNTPRST, ftl::mmio::RW, ftl::mmio::Normal>;
    // Counters Reset When this bit is set, all counters are reset.
    using CNTCLR = ftl::mmio::Field<1, 9, eCNTCLR, ftl::mmio::RW, ftl::mmio::Normal>;
    // Flexible Rx parser Enable When this bit is set to 1, the Programmable Rx Parser functionality is enabled.
    using FRPE = ftl::mmio::Field<1, 15, eFRPE, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MTL_OPERATION_MODE_fields_

