  // FIFO Debug Access Control and Status
  struct MTL_DBG_CTL_fields_ {
    enum class eFDBGEN : std::uint32_t {
      // FIFO Debug Access is disabled
      eDISABLE = 0,
      // FIFO Debug Access is enabled
      eENABLE = 1,
    };

    enum class eDBGMOD : std::uint32_t {
      // Debug Mode Access to FIFO is disabled
      eDISABLE = 0,
      // Debug Mode Access to FIFO is enabled
      eENABLE = 1,
    };

    enum class eBYTEEN : std::uint32_t {
      // Byte 0 valid
      eB0_VAL = 0,
      // Byte 0 and Byte 1 are valid
      eB01_VAL = 1,
      // Byte 0, Byte 1, and Byte 2 are valid
      eB012_VAL = 2,
      // All four bytes are valid
      eB0123_VAL = 3,
    };

    enum class ePKTSTATE : std::uint32_t {
      // Packet Data
      ePKT_DATA = 0,
      // Control Word/Normal Status
      eCW_NS = 1,
      // SOP Data/Last Status
      eSOP_LS = 2,
      // EOP Data/EOP
      eEOP = 3,
    };

    enum class eRSTALL : std::uint32_t {
      // Reset All Pointers is disabled
      eDISABLE = 0,
      // Reset All Pointers is enabled
      eENABLE = 1,
    };

    enum class eRSTSEL : std::uint32_t {
      // Reset Pointers of Selected FIFO is disabled
      eDISABLE = 0,
      // Reset Pointers of Selected FIFO is enabled
      eENABLE = 1,
    };

    enum class eFIFORDEN : std::uint32_t {
      // FIFO Read is disabled
      eDISABLE = 0,
      // FIFO Read is enabled
      eENABLE = 1,
    };

    enum class eFIFOWREN : std::uint32_t {
      // FIFO Write is disabled
      eDISABLE = 0,
      // FIFO Write is enabled
      eENABLE = 1,
    };

    enum class eFIFOSEL : std::uint32_t {
      // Tx FIFO
      eTXFIFO = 0,
      // Tx Status FIFO (only read access when SLVMOD is set)
      eTXSTSFIFO = 1,
      // TSO FIFO (cannot be accessed when SLVMOD is set)
      eTSOFIFO = 2,
      // Rx FIFO
      eRXFIFO = 3,
    };

    enum class ePKTIE : std::uint32_t {
      // Receive Packet Available Interrupt Status is disabled
      eDISABLE = 0,
      // Receive Packet Available Interrupt Status is enabled
      eENABLE = 1,
    };

    enum class eSTSIE : std::uint32_t {
      // Transmit Packet Available Interrupt Status is disabled
      eDISABLE = 0,
      // Transmit Packet Available Interrupt Status is enabled
      eENABLE = 1,
    };

    // FIFO Debug Access Enable When this bit is set, it indicates that the debug mode access to the FIFO is enabled.
    using FDBGEN = ftl::mmio::Field<1, 0, eFDBGEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Debug Mode Access to FIFO When this bit is set, it indicates that the current access to the FIFO is read, write, and debug access.
    using DBGMOD = ftl::mmio::Field<1, 1, eDBGMOD, ftl::mmio::RW, ftl::mmio::Normal>;
    // Byte Enables This field indicates the number of data bytes valid in the data register during Write operation.
    using BYTEEN = ftl::mmio::Field<2, 2, eBYTEEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Encoded Packet State This field is used to write the control information to the Tx FIFO or Rx FIFO.
    using PKTSTATE = ftl::mmio::Field<2, 5, ePKTSTATE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Reset All Pointers When this bit is set, the pointers of all FIFOs are reset when FIFO Debug Access is enabled.
    using RSTALL = ftl::mmio::Field<1, 8, eRSTALL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Reset Pointers of Selected FIFO When this bit is set, the pointers of the currently-selected FIFO are reset when FIFO Debug Access is enabled.
    using RSTSEL = ftl::mmio::Field<1, 9, eRSTSEL, ftl::mmio::RW, ftl::mmio::Normal>;
    // FIFO Read Enable When this bit is set, it enables the Read operation on selected FIFO when FIFO Debug Access is enabled.
    using FIFORDEN = ftl::mmio::Field<1, 10, eFIFORDEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // FIFO Write Enable When this bit is set, it enables the Write operation on selected FIFO when FIFO Debug Access is enabled.
    using FIFOWREN = ftl::mmio::Field<1, 11, eFIFOWREN, ftl::mmio::RW, ftl::mmio::Normal>;
    // FIFO Selected for Access This field indicates the FIFO selected for debug access:
    using FIFOSEL = ftl::mmio::Field<2, 12, eFIFOSEL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Packet Available Interrupt Status Enable When this bit is set, an interrupt is generated when EOP of received packet is written to the Rx FIFO.
    using PKTIE = ftl::mmio::Field<1, 14, ePKTIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Status Available Interrupt Status Enable When this bit is set, an interrupt is generated when Transmit status is available in slave mode.
    using STSIE = ftl::mmio::Field<1, 15, eSTSIE, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MTL_DBG_CTL_fields_

