  // FIFO Debug Status
  struct MTL_DBG_STS_fields_ {
    enum class eFIFOBUSY : std::uint32_t {
      // FIFO Busy not detected
      eINACTIVE = 0,
      // FIFO Busy detected
      eACTIVE = 1,
    };

    enum class ePKTSTATE : std::uint32_t {
      // Packet Data
      ePKT_DATA = 0,
      // Control Word/Normal Status
      eCW_NS = 1,
      // SOP Data/Last Status
      eSOP_LS = 2,
      // EOP Data/EOP
      eEOP = 3,
    };

    enum class eBYTEEN : std::uint32_t {
      // Byte 0 valid
      eB0_VAL = 0,
      // Byte 0 and Byte 1 are valid
      eB01_VAL = 1,
      // Byte 0, Byte 1, and Byte 2 are valid
      eB012_VAL = 2,
      // All four bytes are valid
      eB0123_VAL = 3,
    };

    enum class ePKTI : std::uint32_t {
      // Receive Packet Available Interrupt Status not detected
      eINACTIVE = 0,
      // Receive Packet Available Interrupt Status detected
      eACTIVE = 1,
    };

    enum class eSTSI : std::uint32_t {
      // Transmit Status Available Interrupt Status not detected
      eINACTIVE = 0,
      // Transmit Status Available Interrupt Status detected
      eACTIVE = 1,
    };

    // FIFO Busy When set, this bit indicates that a FIFO operation is in progress in the MAC and content of the following fields is not valid: - All other fields of this register - All fields of the MTL_FIFO_DEBUG_DATA register
    using FIFOBUSY = ftl::mmio::Field<1, 0, eFIFOBUSY, ftl::mmio::RO, ftl::mmio::Normal>;
    // Encoded Packet State This field is used to get the control or status information of the selected FIFO.
    using PKTSTATE = ftl::mmio::Field<2, 1, ePKTSTATE, ftl::mmio::RO, ftl::mmio::Normal>;
    // Byte Enables This field indicates the number of data bytes valid in the data register during Read operation.
    using BYTEEN = ftl::mmio::Field<2, 3, eBYTEEN, ftl::mmio::RO, ftl::mmio::Normal>;
    // Receive Packet Available Interrupt Status When set, this bit indicates that MAC layer has written the EOP of received packet to the Rx FIFO.
    using PKTI = ftl::mmio::Field<1, 8, ePKTI, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Status Available Interrupt Status When set, this bit indicates that the Slave mode Tx packet is transmitted, and the status is available in Tx Status FIFO.
    using STSI = ftl::mmio::Field<1, 9, eSTSI, ftl::mmio::RW, ftl::mmio::Normal>;
    // Remaining Locations in the FIFO Slave Access Mode: This field indicates the space available in selected FIFO.
    using LOCR = ftl::mmio::Field<17, 15, std::uint32_t, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct MTL_DBG_STS_fields_

