  // Queue 1 Transmit Debug
  struct MTL_TXQ1_DEBUG_fields_ {
    enum class eTXQPAUSED : std::uint32_t {
      // Transmit Queue in Pause status is not detected
      eINACTIVE = 0,
      // Transmit Queue in Pause status is detected
      eACTIVE = 1,
    };

    enum class eTRCSTS : std::uint32_t {
      // Idle state
      eIDLE = 0,
      // Read state (transferring data to the MAC transmitter)
      eREAD = 1,
      // Waiting for pending Tx Status from the MAC transmitter
      eWAIT = 2,
      // Flushing the Tx queue because of the Packet Abort request from the MAC
      eFLUSH = 3,
    };

    enum class eTWCSTS : std::uint32_t {
      // MTL Tx Queue Write Controller status is not detected
      eINACTIVE = 0,
      // MTL Tx Queue Write Controller status is detected
      eACTIVE = 1,
    };

    enum class eTXQSTS : std::uint32_t {
      // MTL Tx Queue Not Empty status is not detected
      eINACTIVE = 0,
      // MTL Tx Queue Not Empty status is detected
      eACTIVE = 1,
    };

    enum class eTXSTSFSTS : std::uint32_t {
      // MTL Tx Status FIFO Full status is not detected
      eINACTIVE = 0,
      // MTL Tx Status FIFO Full status is detected
      eACTIVE = 1,
    };

    // Transmit Queue in Pause When this bit is high and the Rx flow control is enabled, it indicates that the Tx Queue is in the Pause condition (in the full-duplex only mode) because of the following: - Reception of the PFC packet for the priorities assigned to the Tx Queue when PFC is enabled - Reception of 802.
    using TXQPAUSED = ftl::mmio::Field<1, 0, eTXQPAUSED, ftl::mmio::RO, ftl::mmio::Normal>;
    // MTL Tx Queue Read Controller Status This field indicates the state of the Tx Queue Read Controller:
    using TRCSTS = ftl::mmio::Field<2, 1, eTRCSTS, ftl::mmio::RO, ftl::mmio::Normal>;
    // MTL Tx Queue Write Controller Status When high, this bit indicates that the MTL Tx Queue Write Controller is active, and it is transferring the data to the Tx Queue.
    using TWCSTS = ftl::mmio::Field<1, 3, eTWCSTS, ftl::mmio::RO, ftl::mmio::Normal>;
    // MTL Tx Queue Not Empty Status When this bit is high, it indicates that the MTL Tx Queue is not empty and some data is left for transmission.
    using TXQSTS = ftl::mmio::Field<1, 4, eTXQSTS, ftl::mmio::RO, ftl::mmio::Normal>;
    // MTL Tx Status FIFO Full Status When high, this bit indicates that the MTL Tx Status FIFO is full.
    using TXSTSFSTS = ftl::mmio::Field<1, 5, eTXSTSFSTS, ftl::mmio::RO, ftl::mmio::Normal>;
    // Number of Packets in the Transmit Queue This field indicates the current number of packets in the Tx Queue.
    using PTXQ = ftl::mmio::Field<3, 16, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // Number of Status Words in Tx Status FIFO of Queue This field indicates the current number of status in the Tx Status FIFO of this queue.
    using STXSTSF = ftl::mmio::Field<3, 20, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct MTL_TXQ1_DEBUG_fields_

