  // Queue 4 Transmit Operation Mode
  struct MTL_TXQ4_OPERATION_MODE_fields_ {
    enum class eFTQ : std::uint32_t {
      // Flush Transmit Queue is disabled
      eDISABLE = 0,
      // Flush Transmit Queue is enabled
      eENABLE = 1,
    };

    enum class eTSF : std::uint32_t {
      // Transmit Store and Forward is disabled
      eDISABLE = 0,
      // Transmit Store and Forward is enabled
      eENABLE = 1,
    };

    enum class eTXQEN : std::uint32_t {
      // Not enabled
      eDISABLE = 0,
      // Enable in AV mode (Reserved in non-AV)
      eEN_IF_AV = 1,
      // Enabled
      eENABLE = 2,
    };

    enum class eTTC : std::uint32_t {
      // 32
      ebf_32BYTES = 0,
      // 64
      ebf_64BYTES = 1,
      // 96
      ebf_96BYTES = 2,
      // 128
      ebf_128BYTES = 3,
      // 192
      ebf_192BYTES = 4,
      // 256
      ebf_256BYTES = 5,
      // 384
      ebf_384BYTES = 6,
      // 512
      ebf_512BYTES = 7,
    };

    // Flush Transmit Queue When this bit is set, the Tx queue controller logic is reset to its default values.
    using FTQ = ftl::mmio::Field<1, 0, eFTQ, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Store and Forward When this bit is set, the transmission starts when a full packet resides in the MTL Tx queue.
    using TSF = ftl::mmio::Field<1, 1, eTSF, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Queue Enable This field is used to enable/disable the transmit queue 0.
    using TXQEN = ftl::mmio::Field<2, 2, eTXQEN, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Threshold Control These bits control the threshold level of the MTL Tx Queue.
    using TTC = ftl::mmio::Field<3, 4, eTTC, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Queue Size This field indicates the size of the allocated Transmit queues in blocks of 256 bytes.
    using TQS = ftl::mmio::Field<5, 16, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct MTL_TXQ4_OPERATION_MODE_fields_

