    using DSPW = ftl::mmio::Field<1, 8, eDSPW, ftl::mmio::RW, ftl::mmio::Normal>;
    // Interrupt Mode This field defines the interrupt mode of DWC_ether_qos.
    using INTM = ftl::mmio::Field<2, 16, eINTM, ftl::mmio::RW, ftl::mmio::Normal>;
