    using RxPBL = ftl::mmio::Field<6, 16, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Rx Packet Flush.
    using RPF = ftl::mmio::Field<1, 31, eRPF, ftl::mmio::RW, ftl::mmio::Normal>;
