  // DMA Channel 1 Status
  struct DMA_CH1_STATUS_fields_ {
    enum class eTI : std::uint32_t {
      // Transmit Interrupt status not detected
      eINACTIVE = 0,
      // Transmit Interrupt status detected
      eACTIVE = 1,
    };

    enum class eTPS : std::uint32_t {
      // Transmit Process Stopped status not detected
      eINACTIVE = 0,
      // Transmit Process Stopped status detected
      eACTIVE = 1,
    };

    enum class eTBU : std::uint32_t {
      // Transmit Buffer Unavailable status not detected
      eINACTIVE = 0,
      // Transmit Buffer Unavailable status detected
      eACTIVE = 1,
    };

    enum class eRI : std::uint32_t {
      // Receive Interrupt status not detected
      eINACTIVE = 0,
      // Receive Interrupt status detected
      eACTIVE = 1,
    };

    enum class eRBU : std::uint32_t {
      // Receive Buffer Unavailable status not detected
      eINACTIVE = 0,
      // Receive Buffer Unavailable status detected
      eACTIVE = 1,
    };

    enum class eRPS : std::uint32_t {
      // Receive Process Stopped status not detected
      eINACTIVE = 0,
      // Receive Process Stopped status detected
      eACTIVE = 1,
    };

    enum class eRWT : std::uint32_t {
      // Receive Watchdog Timeout status not detected
      eINACTIVE = 0,
      // Receive Watchdog Timeout status detected
      eACTIVE = 1,
    };

    enum class eETI : std::uint32_t {
      // Early Transmit Interrupt status not detected
      eINACTIVE = 0,
      // Early Transmit Interrupt status detected
      eACTIVE = 1,
    };

    enum class eERI : std::uint32_t {
      // Early Receive Interrupt status not detected
      eINACTIVE = 0,
      // Early Receive Interrupt status detected
      eACTIVE = 1,
    };

    enum class eFBE : std::uint32_t {
      // Fatal Bus Error status not detected
      eINACTIVE = 0,
      // Fatal Bus Error status detected
      eACTIVE = 1,
    };

    enum class eCDE : std::uint32_t {
      // Context Descriptor Error status not detected
      eINACTIVE = 0,
      // Context Descriptor Error status detected
      eACTIVE = 1,
    };

    enum class eAIS : std::uint32_t {
      // Abnormal Interrupt Summary status not detected
      eINACTIVE = 0,
      // Abnormal Interrupt Summary status detected
      eACTIVE = 1,
    };

    enum class eNIS : std::uint32_t {
      // Normal Interrupt Summary status not detected
      eINACTIVE = 0,
      // Normal Interrupt Summary status detected
      eACTIVE = 1,
    };

    // Transmit Interrupt This bit indicates that the packet transmission is complete.
    using TI = ftl::mmio::Field<1, 0, eTI, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Process Stopped This bit is set when the transmission is stopped.
    using TPS = ftl::mmio::Field<1, 1, eTPS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Buffer Unavailable This bit indicates that the application owns the next descriptor in the Transmit list, and the DMA cannot acquire it.
    using TBU = ftl::mmio::Field<1, 2, eTBU, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Interrupt This bit indicates that the packet reception is complete.
    using RI = ftl::mmio::Field<1, 6, eRI, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Buffer Unavailable This bit indicates that the application owns the next descriptor in the Receive list, and the DMA cannot acquire it.
    using RBU = ftl::mmio::Field<1, 7, eRBU, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Process Stopped This bit is asserted when the Rx process enters the Stopped state.
    using RPS = ftl::mmio::Field<1, 8, eRPS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Watchdog Timeout This bit is asserted when a packet with length greater than 2,048 bytes (10,240 bytes when Jumbo Packet mode is enabled) is received.
    using RWT = ftl::mmio::Field<1, 9, eRWT, ftl::mmio::RW, ftl::mmio::Normal>;
    // Early Transmit Interrupt This bit when set indicates that the TxDMA has completed the transfer of packet data to the MTL TXFIFO memory.
    using ETI = ftl::mmio::Field<1, 10, eETI, ftl::mmio::RW, ftl::mmio::Normal>;
    // Early Receive Interrupt This bit when set indicates that the RxDMA has completed the transfer of packet data to the memory.
    using ERI = ftl::mmio::Field<1, 11, eERI, ftl::mmio::RW, ftl::mmio::Normal>;
    // Fatal Bus Error This bit indicates that a bus error occurred (as described in the EB field).
    using FBE = ftl::mmio::Field<1, 12, eFBE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Context Descriptor Error This bit indicates that the DMA Tx/Rx engine received a descriptor error, which indicates invalid context in the middle of packet flow ( intermediate descriptor) or all one's descriptor in Tx case and on Rx side it indicates DMA has read a descriptor with either of the buffer address as ones which is considered to be invalid.
    using CDE = ftl::mmio::Field<1, 13, eCDE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Abnormal Interrupt Summary Abnormal Interrupt Summary bit value is the logical OR of the following when the corresponding interrupt bits are enabled in the INTERRUPT_ENABLE register: - Bit 1: Transmit Process Stopped - Bit 7: Receive Buffer Unavailable - Bit 8: Receive Process Stopped - Bit 10: Early Transmit Interrupt - Bit 12: Fatal Bus Error - Bit 13: Context Descriptor Error Only unmasked bits affect the Abnormal Interrupt Summary bit.
    using AIS = ftl::mmio::Field<1, 14, eAIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Normal Interrupt Summary Normal Interrupt Summary bit value is the logical OR of the following bits when the corresponding interrupt bits are enabled in the INTERRUPT_ENABLE register: - Bit 0: Transmit Interrupt - Bit 2: Transmit Buffer Unavailable - Bit 6: Receive Interrupt - Bit 11: Early Receive Interrupt Only unmasked bits (interrupts for which interrupt enable is set in INTERRUPT_ENABLE register) affect the Normal Interrupt Summary bit.
    using NIS = ftl::mmio::Field<1, 15, eNIS, ftl::mmio::RW, ftl::mmio::Normal>;
    // Tx DMA Error Bits This field indicates the type of error that caused a Bus Error.
    using TEB = ftl::mmio::Field<3, 16, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
    // Rx DMA Error Bits This field indicates the type of error that caused a Bus Error.
    using REB = ftl::mmio::Field<3, 19, std::uint8_t, ftl::mmio::RO, ftl::mmio::Normal>;
  };  // struct DMA_CH1_STATUS_fields_

