  // Channel 2 Interrupt Enable
  struct DMA_CH2_INTERRUPT_ENABLE_fields_ {
    enum class eTIE : std::uint32_t {
      // Transmit Interrupt is disabled
      eDISABLE = 0,
      // Transmit Interrupt is enabled
      eENABLE = 1,
    };

    enum class eTXSE : std::uint32_t {
      // Transmit Stopped is disabled
      eDISABLE = 0,
      // Transmit Stopped is enabled
      eENABLE = 1,
    };

    enum class eTBUE : std::uint32_t {
      // Transmit Buffer Unavailable is disabled
      eDISABLE = 0,
      // Transmit Buffer Unavailable is enabled
      eENABLE = 1,
    };

    enum class eRIE : std::uint32_t {
      // Receive Interrupt is disabled
      eDISABLE = 0,
      // Receive Interrupt is enabled
      eENABLE = 1,
    };

    enum class eRBUE : std::uint32_t {
      // Receive Buffer Unavailable is disabled
      eDISABLE = 0,
      // Receive Buffer Unavailable is enabled
      eENABLE = 1,
    };

    enum class eRSE : std::uint32_t {
      // Receive Stopped is disabled
      eDISABLE = 0,
      // Receive Stopped is enabled
      eENABLE = 1,
    };

    enum class eRWTE : std::uint32_t {
      // Receive Watchdog Timeout is disabled
      eDISABLE = 0,
      // Receive Watchdog Timeout is enabled
      eENABLE = 1,
    };

    enum class eETIE : std::uint32_t {
      // Early Transmit Interrupt is disabled
      eDISABLE = 0,
      // Early Transmit Interrupt is enabled
      eENABLE = 1,
    };

    enum class eERIE : std::uint32_t {
      // Early Receive Interrupt is disabled
      eDISABLE = 0,
      // Early Receive Interrupt is enabled
      eENABLE = 1,
    };

    enum class eFBEE : std::uint32_t {
      // Fatal Bus Error is disabled
      eDISABLE = 0,
      // Fatal Bus Error is enabled
      eENABLE = 1,
    };

    enum class eCDEE : std::uint32_t {
      // Context Descriptor Error is disabled
      eDISABLE = 0,
      // Context Descriptor Error is enabled
      eENABLE = 1,
    };

    enum class eAIE : std::uint32_t {
      // Abnormal Interrupt Summary is disabled
      eDISABLE = 0,
      // Abnormal Interrupt Summary is enabled
      eENABLE = 1,
    };

    enum class eNIE : std::uint32_t {
      // Normal Interrupt Summary is disabled
      eDISABLE = 0,
      // Normal Interrupt Summary is enabled
      eENABLE = 1,
    };

    // Transmit Interrupt Enable When this bit is set along with the NIE bit, the Transmit Interrupt is enabled.
    using TIE = ftl::mmio::Field<1, 0, eTIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Stopped Enable When this bit is set along with the AIE bit, the Transmission Stopped interrupt is enabled.
    using TXSE = ftl::mmio::Field<1, 1, eTXSE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Buffer Unavailable Enable When this bit is set along with the NIE bit, the Transmit Buffer Unavailable interrupt is enabled.
    using TBUE = ftl::mmio::Field<1, 2, eTBUE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Interrupt Enable When this bit is set along with the NIE bit, the Receive Interrupt is enabled.
    using RIE = ftl::mmio::Field<1, 6, eRIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Buffer Unavailable Enable When this bit is set along with the AIE bit, the Receive Buffer Unavailable interrupt is enabled.
    using RBUE = ftl::mmio::Field<1, 7, eRBUE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Stopped Enable When this bit is set along with the AIE bit, the Receive Stopped Interrupt is enabled.
    using RSE = ftl::mmio::Field<1, 8, eRSE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Watchdog Timeout Enable When this bit is set along with the AIE bit, the Receive Watchdog Timeout interrupt is enabled.
    using RWTE = ftl::mmio::Field<1, 9, eRWTE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Early Transmit Interrupt Enable When this bit is set along with the AIE bit, the Early Transmit interrupt is enabled.
    using ETIE = ftl::mmio::Field<1, 10, eETIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Early Receive Interrupt Enable When this bit is set along with the NIE bit, the Early Receive interrupt is enabled.
    using ERIE = ftl::mmio::Field<1, 11, eERIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Fatal Bus Error Enable When this bit is set along with the AIE bit, the Fatal Bus error interrupt is enabled.
    using FBEE = ftl::mmio::Field<1, 12, eFBEE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Context Descriptor Error Enable When this bit is set along with the AIE bit, the Descriptor error interrupt is enabled.
    using CDEE = ftl::mmio::Field<1, 13, eCDEE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Abnormal Interrupt Summary Enable When this bit is set, the abnormal interrupt summary is enabled.
    using AIE = ftl::mmio::Field<1, 14, eAIE, ftl::mmio::RW, ftl::mmio::Normal>;
    // Normal Interrupt Summary Enable When this bit is set, the normal interrupt summary is enabled.
    using NIE = ftl::mmio::Field<1, 15, eNIE, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct DMA_CH2_INTERRUPT_ENABLE_fields_

