  // DMA Channel 3 Transmit Control
  struct DMA_CH3_TX_CONTROL_fields_ {
    enum class eST : std::uint32_t {
      // Stop Transmission Command
      eSTOP = 0,
      // Start Transmission Command
      eSTART = 1,
    };

    enum class eOSF : std::uint32_t {
      // Operate on Second Packet disabled
      eDISABLE = 0,
      // Operate on Second Packet enabled
      eENABLE = 1,
    };

    enum class eIPBL : std::uint32_t {
      // Ignore PBL Requirement is disabled
      eDISABLE = 0,
      // Ignore PBL Requirement is enabled
      eENABLE = 1,
    };

    enum class eEDSE : std::uint32_t {
      // Enhanced Descriptor is disabled
      eDISABLE = 0,
      // Enhanced Descriptor is enabled
      eENABLE = 1,
    };

    // Start or Stop Transmission Command When this bit is set, transmission is placed in the Running state.
    using ST = ftl::mmio::Field<1, 0, eST, ftl::mmio::RW, ftl::mmio::Normal>;
    // Operate on Second Packet When this bit is set, it instructs the DMA to process the second packet of the Transmit data even before the status for the first packet is obtained.
    using OSF = ftl::mmio::Field<1, 4, eOSF, ftl::mmio::RW, ftl::mmio::Normal>;
    // Ignore PBL Requirement When this bit is set, the DMA does not check for PBL number of locations in the MTL before initiating a transfer.
    using IPBL = ftl::mmio::Field<1, 15, eIPBL, ftl::mmio::RW, ftl::mmio::Normal>;
    // Transmit Programmable Burst Length These bits indicate the maximum number of beats to be transferred in one DMA block data transfer.
    using TxPBL = ftl::mmio::Field<6, 16, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Enhanced Descriptor Enable When this bit is set, the corresponding channel uses Enhanced Descriptors that are 32 Bytes for both Normal and Context Descriptors.
    using EDSE = ftl::mmio::Field<1, 28, eEDSE, ftl::mmio::RW, ftl::mmio::Normal>;
  };  // struct DMA_CH3_TX_CONTROL_fields_

