    // Start or Stop Receive When this bit is set, the DMA tries to acquire the descriptor from the Receive list and processes the incoming packets.
    using SR = ftl::mmio::Field<1, 0, eSR, ftl::mmio::RW, ftl::mmio::Normal>;
