    using RBSZ_13_y = ftl::mmio::Field<11, 4, std::uint16_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Receive Programmable Burst Length These bits indicate the maximum number of beats to be transferred in one DMA block data transfer.
    using RxPBL = ftl::mmio::Field<6, 16, std::uint8_t, ftl::mmio::RW, ftl::mmio::Normal>;
    // Rx Packet Flush.
    using RPF = ftl::mmio::Field<1, 31, eRPF, ftl::mmio::RW, ftl::mmio::Normal>;
